/*
 * A331460  Irregular triangle read by rows in which row n is the result of
 *          iterating the operation f(n) = n/7 if n == 0 (mod 7), otherwise
 *          f(n) = 7*(n + ceiling(n/7)), terminating at the first occurrence
 *          of 1.
 * https://oeis.org/A331460
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, tabf
 * Formula:   a(n) is the n‑th element of the concatenation of the rows of the
 *            irregular triangle whose rows are generated by iterating f(x) =
 *            x/7 if x ≡ 0 (mod 7), otherwise f(x) = 7*(x + ceil(x/7)), until
 *            the value 1 is reached
 * Range:     u8 n <= 71, u16 n <= 71, u32 n <= 71, u64 n <= 71, u128 n <= 71,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* --- Forward declaration of the next‑value function for m = 7 --- */
static inline seq_t f_next(seq_t x)
{
    if ((x % 7) == 0)
        return x / 7;
    /* ceil(x/7) = (x-1)/7 + 1 for x > 0 */
    seq_t ceil_x = ((x - 1) / 7) + 1;
    return 7 * (x + ceil_x);
}

/* --- Static cache for the sequence values --- */
static seq_t *cache = NULL;      /* dynamic array of seq_t values */
static size_t cache_len = 0;     /* number of values stored so far */
static size_t cache_cap = 0;     /* current capacity of the array */
static idx_t next_start = 1;     /* next row start value */

/* Grow the cache to hold at least 'needed' elements. */
static void grow_cache(size_t needed)
{
    if (needed <= cache_cap)
        return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    while (new_cap < needed)
        new_cap <<= 1;
    seq_t *ptr = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!ptr)
        abort(); /* allocation failure */
    cache = ptr;
    cache_cap = new_cap;
}

/* Return the n-th term (1‑based) of the sequence. */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;   /* undefined for n==0, return 0 */

    /* Generate rows until we have at least n values stored. */
    while (cache_len < (size_t)n) {
        seq_t val = (seq_t)next_start;   /* start of the next row */
        while (1) {
            grow_cache(cache_len + 1);
            cache[cache_len++] = val;
            if (val == (seq_t)1)
                break;
            val = f_next(val);
        }
        ++next_start;
    }
    return cache[n - 1];
}
